// Minimal ESLint flat config for the Rails 8 scaffold.
// Rails 8 does not ship an ESLint config; this file exists so that a
// global pre-commit hook running `npx eslint` does not fail on the
// stock Turbo/Stimulus JavaScript files generated by `rails new`.
//
// We explicitly ignore all JavaScript under app/javascript, vendor/,
// and the PWA service worker. These files are maintained by Rails
// generators and should not be linted with a generic ESLint ruleset.
module.exports = [
  {
    ignores: [
      "app/javascript/**",
      "app/views/pwa/**",
      "vendor/**",
      "public/**",
      "tmp/**",
      "log/**",
      "db/**",
      "storage/**",
    ],
  },
];
